contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 inputAmount, uint16 newFeeRate) public {
        require(true);

        uint256 feeRateBefore = c.feeRate();
        uint256 protocolFeeRate = Factory(c.factory()).protocolFeeRate();

        bool reverted;
        try c.setFeeRate(newFeeRate) { reverted = false; } catch { reverted = true; }

        if (newFeeRate > 5_000) {
            assert(reverted && c.feeRate() == feeRateBefore);
        } else {
            assert(!reverted && c.feeRate() == newFeeRate);
        }

        (uint256 feeAmount, uint256 protocolFeeAmount) = c.changeFeeQuote(inputAmount);
        uint256 exponent = c.baseToken() == address(0) ? 14 : 0;
        uint256 feePerNft = uint256(c.changeFee()) * (10 ** exponent);
        uint256 expectedFeeAmount = inputAmount * feePerNft / 1e18;
        uint256 expectedProtocolFeeAmount = expectedFeeAmount * protocolFeeRate / 10_000;

        assert(feeAmount == expectedFeeAmount && protocolFeeAmount == expectedProtocolFeeAmount);
    }

    receive() external payable {}
}

