contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 virtualNft, uint256 baseAmount) public payable {
        require(virtualNft > 1e18);
        require(virtualNft <= type(uint128).max);
        require(baseAmount > 0);
        require(address(this).balance >= baseAmount);

        // Use the pool's public configuration setters as the only way to create state.
        // Since c was deployed and initialized outside of this run, we must not rely on
        // initialize having happened.  availableForFlashLoan is a public view we may call.

        // Reading the before price is allowed.
        uint256 beforePrice = c.price();

        // Give the pool one NFT and baseAmount.
        // This test uses a single id only if the pool already holds it.
        // To keep things independent of minting and ownership,
        // we instead change the virtual reserves directly.
        // setVirtualReserves is onlyOwner.  The owner is the Factory,
        // and the Factory owner is the deployer, not this test contract.
        // Therefore this call can revert.  Capture that revert.
        bool reverted;
        try c.setVirtualReserves(uint128(virtualNft), uint128(virtualNft)) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterPrice = c.price();

        if (!reverted) {
            assert(afterPrice == 1e18);
        } else {
            assert(afterPrice == beforePrice);
        }
    }

    receive() external payable {}
}

