contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    receive() external payable {}

    function run(
        uint256[] calldata tokenIds,
        uint256[] calldata tokenWeights,
        C.MerkleMultiProof calldata proof,
        uint256 buyAmount
    ) public payable {
        require(address(this).balance >= buyAmount, "insufficient balance");

        uint256 maxWeight = c.virtualNftReserves() - 1;
        uint256 weightSum = 0;
        for (uint256 i = 0; i < tokenWeights.length; i++) {
            weightSum += tokenWeights[i];
        }
        require(weightSum <= maxWeight, "weight sum too high");

        (uint256 netInputAmount, uint256 feeAmount, uint256 protocolFeeAmount) = c.buyQuote(weightSum);
        require(buyAmount >= netInputAmount, "insufficient payment");

        uint256 nftReservesBefore = c.virtualNftReserves();
        uint256 baseReservesBefore = c.virtualBaseTokenReserves();

        (uint256 actualNetInput, uint256 actualFee, uint256 actualProtocolFee) = c.buy{value: buyAmount}(tokenIds, tokenWeights, proof);

        assert(actualNetInput == netInputAmount && actualFee == feeAmount && actualProtocolFee == protocolFeeAmount &&
               c.virtualNftReserves() == nftReservesBefore - weightSum &&
               c.virtualBaseTokenReserves() >= baseReservesBefore);
    }
}

