contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint128 vBase, uint128 vNft, uint16 fRate, uint16 pFee, uint256 outputAmount) public payable {
        require(vNft > 0);
        require(outputAmount < uint256(vNft));
        require(fRate <= 5000);

        c.setAllParameters(vBase, vNft, bytes32(0), fRate, false, true);

        (uint256 netInputAmount, uint256 feeAmount, uint256 protocolFeeAmount) = c.buyQuote(outputAmount);

        uint256 inputAmount = (outputAmount * uint256(vBase) + (uint256(vNft) - outputAmount) - 1) / (uint256(vNft) - outputAmount);
        uint256 expectedProtocolFee = inputAmount * uint256(pFee) / 10000;
        uint256 expectedFee = inputAmount * uint256(fRate) / 10000;
        uint256 expectedNetInput = inputAmount + expectedFee + expectedProtocolFee;

        assert(netInputAmount == expectedNetInput);
    }

    receive() external payable {}
}

