    ) public payable {
        c.initialize(
            address(0),
            address(this),
            1e18,
            1e18,
            0,
            0,
            bytes32(0),
            false,
            false
        );

        uint256 beforeBalance = address(c).balance;

        C.MerkleMultiProof memory emptyProof;
        emptyProof.proof = new bytes32[](0);
        emptyProof.flags = new bool[](0);

        IStolenNftOracle.Message[] memory emptyStolen;
